import re

_KEY = re.compile(r"^[A-Za-z_][A-Za-z0-9_.-]*$")

def parse_config(text):
    result = {}
    for lineno, raw in enumerate(text.splitlines(), start=1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        key, sep, value = line.partition("=")
        if not sep:
            raise ValueError(f"line {lineno}: expected key = value")
        key = key.strip()
        if not _KEY.match(key):
            raise ValueError(f"line {lineno}: invalid key {key!r}")
        result[key] = _parse_value(value.strip(), lineno)
    return result

def _parse_value(value, lineno):
    if value.startswith('"'):
        out = []
        i = 1
        while i < len(value):
            ch = value[i]
            if ch == "\\" and i + 1 < len(value):
                out.append(value[i + 1])
                i += 2
            elif ch == '"':
                rest = value[i + 1:].strip()
                if rest and not rest.startswith("#"):
                    raise ValueError(f"line {lineno}: trailing characters after quote")
                return "".join(out)
            else:
                out.append(ch)
                i += 1
        raise ValueError(f"line {lineno}: unterminated quote")
    if " #" in value:
        value = value.split(" #", 1)[0]
    return value.strip()
```

How each spec clause is met:

- **Comments and blanks:** skipped before any parsing, so a `#` line never reaches the key check.
- **Quoted values:** the scanner walks character by character; a backslash consumes the next character literally, which handles both `\"` and `\\`, and `=` / `#` inside quotes are never treated specially.
- **Unquoted values:** a trailing comment is only stripped at a ` #` boundary, so a value like `a#b` keeps its `#`.
- **Duplicates:** plain dict assignment — the last occurrence wins, as specified.
- **Errors:** all three failure modes (no `=`, bad key, unterminated quote) raise ValueError carrying the line number from `enumerate(..., start=1)`.

