def levenshtein(a, b):
    if len(a) < len(b):
        a, b = b, a
    previous = list(range(len(b) + 1))
    for i, ca in enumerate(a, start=1):
        current = [i]
        for j, cb in enumerate(b, start=1):
            current.append(min(
                previous[j] + 1,                 # delete ca
                current[j - 1] + 1,              # insert cb
                previous[j - 1] + (ca != cb),    # substitute or match
            ))
        previous = current
    return previous[-1]


