class IniConfig:
    def __init__(self, text):
        self._data = {"DEFAULT": {}}
        section = "DEFAULT"
        for lineno, raw in enumerate(text.splitlines(), start=1):
            line = raw.strip()
            if not line or line.startswith((";", "#")):
                continue
            if line.startswith("[") and line.endswith("]"):
                section = line[1:-1].strip()
                if not section:
                    raise ValueError(f"line {lineno}: empty section name")
                self._data.setdefault(section, {})
                continue
            key, sep, value = line.partition("=")
            if not sep:
                key, sep, value = line.partition(":")
            if not sep:
                raise ValueError(f"line {lineno}: expected key = value")
            self._data[section][key.strip()] = value.strip()

    def get(self, section, key, default=None):
        return self._data.get(section, {}).get(key, default)

    def _typed(self, section, key, conv, default):
        raw = self.get(section, key)
        if raw is None:
            if default is None:
                raise KeyError(f"{section}.{key}")
            return default
        return conv(raw)

    def getint(self, section, key, default=None):
        return self._typed(section, key, int, default)

    def getfloat(self, section, key, default=None):
        return self._typed(section, key, float, default)

    def getbool(self, section, key, default=None):
        def conv(raw):
            v = raw.strip().lower()
            if v in ("true", "yes", "on"):
                return True
            if v in ("false", "no", "off"):
                return False
            raise ValueError(f"not a boolean: {raw!r}")
        return self._typed(section, key, conv, default)
```

How each spec clause is met:

- **DEFAULT section:** the data dict is seeded with it and the current section starts there, so pre-section keys land in it naturally.
- **Merging and last-wins:** `setdefault` on a repeated header keeps the existing dict, and plain assignment overwrites duplicate keys.
- **Two separators:** `=` is tried first via `partition`; only if it is absent does the line fall back to `:`, so a value containing a colon (like a URL) is safe when `=` is the separator.
- **Getter contract:** `_typed` centralizes the missing-key rule — KeyError when no default was passed, the default otherwise — and conversion errors (including getbool's ValueError) propagate from the converter itself.

