import re

_TOKEN_KINDS = [
    ("op", r"==|!=|<=|>=|<|>"),
    ("lparen", r"\("),
    ("rparen", r"\)"),
    ("str", r"'[^']*'"),
    ("num", r"\d+(?:\.\d+)?"),
    ("ident", r"[A-Za-z_][A-Za-z0-9_]*"),
]
_TOKEN = re.compile("|".join("(?P<%s>%s)" % (k, p) for k, p in _TOKEN_KINDS))

def tokenize(text):
    tokens, pos = [], 0
    while pos < len(text):
        if text[pos].isspace():
            pos += 1
            continue
        m = _TOKEN.match(text, pos)
        if not m:
            raise ValueError(f"unexpected character at {pos}: {text[pos]!r}")
        pos = m.end()
        kind = m.lastgroup
        value = m.group()
        if kind == "ident" and value.upper() in ("AND", "OR", "NOT"):
            tokens.append((value.upper(), value))
        elif kind == "str":
            tokens.append(("VALUE", value[1:-1]))
        elif kind == "num":
            tokens.append(("VALUE", float(value) if "." in value else int(value)))
        elif kind == "ident" and value.lower() in ("true", "false"):
            tokens.append(("VALUE", value.lower() == "true"))
        elif kind == "ident":
            tokens.append(("IDENT", value))
        else:
            tokens.append((value, value))
    tokens.append(("EOF", None))
    return tokens

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.i = 0

    def peek(self):
        return self.tokens[self.i][0]

    def next(self):
        tok = self.tokens[self.i]
        self.i += 1
        return tok

    def parse(self):
        node = self.parse_or()
        if self.peek() != "EOF":
            raise ValueError(f"unexpected trailing token {self.tokens[self.i][1]!r}")
        return node

    def parse_or(self):
        node = self.parse_and()
        while self.peek() == "OR":
            self.next()
            node = ("or", node, self.parse_and())
        return node

    def parse_and(self):
        node = self.parse_not()
        while self.peek() == "AND":
            self.next()
            node = ("and", node, self.parse_not())
        return node

    def parse_not(self):
        if self.peek() == "NOT":
            self.next()
            return ("not", self.parse_not())
        return self.parse_atom()

    def parse_atom(self):
        if self.peek() == "(":
            self.next()
            node = self.parse_or()
            if self.next()[0] != ")":
                raise ValueError("expected )")
            return node
        ident = self.next()
        if ident[0] != "IDENT":
            raise ValueError(f"expected field name, got {ident[1]!r}")
        op = self.next()
        if op[0] not in ("==", "!=", "<", "<=", ">", ">="):
            raise ValueError(f"expected comparison operator, got {op[1]!r}")
        val = self.next()
        if val[0] != "VALUE":
            raise ValueError(f"expected value, got {val[1]!r}")
        return ("cmp", ident[1], op[0], val[1])

_OPS = {"==": lambda a, b: a == b, "!=": lambda a, b: a != b,
        "<": lambda a, b: a < b, "<=": lambda a, b: a <= b,
        ">": lambda a, b: a > b, ">=": lambda a, b: a >= b}

def evaluate(node, record):
    kind = node[0]
    if kind == "or":
        return evaluate(node[1], record) or evaluate(node[2], record)
    if kind == "and":
        return evaluate(node[1], record) and evaluate(node[2], record)
    if kind == "not":
        return not evaluate(node[1], record)
    _, field, op, expected = node
    if field not in record:
        return False
    return _OPS[op](record[field], expected)

def parse_filter(text):
    return Parser(tokenize(text)).parse()
```

How each spec clause is met:

- **Precedence:** the call chain parse_or → parse_and → parse_not → parse_atom encodes OR < AND < NOT < atoms directly in the grammar, so `a == 1 OR b == 2 AND NOT c == 3` groups as `a OR (b AND (NOT c))` with no precedence table.
- **Case-insensitive keywords:** identifiers are upper-cased for the keyword check before being treated as field names; a field literally named `andrew` is safe because the whole token must equal AND/OR/NOT.
- **Missing fields:** `evaluate` returns False for a `cmp` node whose field is absent — for every operator, including `!=`, exactly as specified (no three-valued logic leaks out).
- **Error surface:** the tokenizer reports the offending character position, the parser rejects trailing tokens, and both raise ValueError as required.

