class Fenwick:
    def __init__(self, values):
        self.n = len(values)
        self.bit = [0] * (self.n + 1)
        for i, v in enumerate(values):
            self.add(i, v)

    def add(self, index, delta):
        i = index + 1
        while i <= self.n:
            self.bit[i] += delta
            i += i & -i

    def prefix_sum(self, count):
        total = 0
        i = count
        while i > 0:
            total += self.bit[i]
            i -= i & -i
        return total

    def range_sum(self, lo, hi):
        return self.prefix_sum(hi + 1) - self.prefix_sum(lo)


fw = Fenwick([2, 1, 1, 3, 2, 3, 4, 5, 7, 8, 9])
print("prefix(5) =", fw.prefix_sum(5))
print("range(3..7) =", fw.range_sum(3, 7))
fw.add(2, 4)
print("after add(index 2, +4): prefix(5) =", fw.prefix_sum(5))
print("total =", fw.prefix_sum(11))

