def normalize_phone(raw, default_cc="1"):
    s = raw.strip()
    for ch in " -()":
        s = s.replace(ch, "")
    if any(c.isalpha() for c in s):
        raise ValueError("invalid characters")
    if s.startswith("00"):
        s = "+" + s[2:]
    if s.startswith("+"):
        digits = s[1:]
        if not digits.isdigit():
            raise ValueError("invalid characters")
    else:
        if not s.isdigit():
            raise ValueError("invalid characters")
        if len(s) == 10:
            digits = default_cc + s
        elif s.startswith(default_cc) and len(s) == 10 + len(default_cc):
            digits = s
        else:
            raise ValueError("ambiguous number: missing country code")
    if not (8 <= len(digits) <= 15):
        raise ValueError("invalid length")
    return "+" + digits


