import time

class CircuitOpenError(Exception):
    pass

class CircuitBreaker:
    def __init__(self, failure_threshold=3, reset_timeout=30.0, clock=time.monotonic):
        if failure_threshold < 1:
            raise ValueError("failure_threshold must be >= 1")
        self.failure_threshold = failure_threshold
        self.reset_timeout = reset_timeout
        self.clock = clock
        self._failures = 0
        self._opened_at = None

    @property
    def state(self):
        if self._opened_at is None:
            return "closed"
        if self.clock() - self._opened_at >= self.reset_timeout:
            return "half_open"
        return "open"

    def call(self, fn, *args, **kwargs):
        state = self.state
        if state == "open":
            raise CircuitOpenError("circuit is open")
        try:
            result = fn(*args, **kwargs)
        except Exception:
            self._on_failure(state)
            raise
        self._on_success()
        return result

    def _on_success(self):
        self._failures = 0
        self._opened_at = None

    def _on_failure(self, state):
        self._failures += 1
        if state == "half_open" or self._failures >= self.failure_threshold:
            self._opened_at = self.clock()
```

How each spec clause is met:

- **Derived state:** there is no stored state variable to get out of sync — `state` is computed from `_opened_at` and the injected clock, so the open → half-open transition happens automatically as time passes, with no timers or background threads.
- **Fail-fast while open:** `call` checks the state before touching `fn`, so a rejected call has zero side effects on the downstream service.
- **Half-open trial:** the state snapshot is taken once at the top of `call` and passed to `_on_failure`, so a failed trial re-opens with a *fresh* timestamp even though the failure counter alone wouldn't have reached the threshold.
- **Consecutive, not cumulative:** `_on_success` zeroes the counter, so intermittent failures separated by successes never trip the breaker.

