import heapq


class CycleError(Exception):
    pass


def topo_sort(tasks):
    indegree = {name: 0 for name in tasks}
    dependents = {name: [] for name in tasks}
    for name, deps in tasks.items():
        for d in deps:
            if d not in tasks:
                raise KeyError(f"unknown dependency {d!r} of {name!r}")
            indegree[name] += 1
            dependents[d].append(name)
    ready = [n for n, deg in indegree.items() if deg == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        n = heapq.heappop(ready)
        order.append(n)
        for m in dependents[n]:
            indegree[m] -= 1
            if indegree[m] == 0:
                heapq.heappush(ready, m)
    if len(order) != len(tasks):
        stuck = sorted(n for n, deg in indegree.items() if deg > 0)
        raise CycleError(f"dependency cycle involving: {', '.join(stuck)}")
    return order


build = {"compile": [], "test": ["compile"], "package": ["compile"],
         "deploy": ["test", "package"], "docs": []}
print(topo_sort(build))
try:
    topo_sort({"a": ["b"], "b": ["a"], "c": []})
except CycleError as e:
    print("CycleError:", e)

