import time
from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity, clock=time.monotonic):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self.clock = clock
        self._data = OrderedDict()   # key -> (value, expires_at); LRU first

    def _purge_expired(self):
        now = self.clock()
        for key in [k for k, (_, exp) in self._data.items() if exp <= now]:
            del self._data[key]

    def get(self, key):
        item = self._data.get(key)
        if item is None:
            return None
        value, expires_at = item
        if expires_at <= self.clock():
            del self._data[key]
            return None
        self._data.move_to_end(key)
        return value

    def put(self, key, value, ttl_seconds):
        if ttl_seconds <= 0:
            raise ValueError("ttl must be positive")
        self._data.pop(key, None)
        self._data[key] = (value, self.clock() + ttl_seconds)
        if len(self._data) > self.capacity:
            self._purge_expired()
        while len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self):
        self._purge_expired()
        return len(self._data)
```

How each spec clause is met:

- **Recency without renewal:** `get` calls `move_to_end` (refreshing LRU position) but never touches `expires_at` — the two lifetimes the spec separates stay separate.
- **Eviction order on put:** expired entries are purged first, and only if the cache is *still* over capacity does LRU eviction (`popitem(last=False)`) run — live entries are never evicted to make room while dead ones remain.
- **Lazy expiry:** there is no sweeper thread; expiry is enforced at the three observation points (get, put overflow, len), which is what makes the injectable clock sufficient for deterministic tests.
- **Update semantics:** re-putting an existing key pops and re-inserts it, so it becomes most-recently-used with a fresh expiry, as a new entry should.

