pub struct Parser<'a> {
    bytes: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    pub fn new(input: &'a str) -> Self {
        Parser { bytes: input.as_bytes(), pos: 0 }
    }

    fn peek(&self) -> Option<u8> {
        self.bytes.get(self.pos).copied()
    }

    fn skip_ws(&mut self) {
        while self.peek().map_or(false, |b| b.is_ascii_whitespace()) {
            self.pos += 1;
        }
    }

    pub fn parse_expr(&mut self) -> Result<i64, String> {
        let mut lhs = self.parse_term()?;
        loop {
            self.skip_ws();
            match self.peek() {
                Some(b'+') => {
                    self.pos += 1;
                    let rhs = self.parse_term()?;
                    lhs = lhs.checked_add(rhs).ok_or_else(|| "overflow".to_string())?;
                }
                Some(b'-') => {
                    self.pos += 1;
                    let rhs = self.parse_term()?;
                    lhs = lhs.checked_sub(rhs).ok_or_else(|| "overflow".to_string())?;
                }
                _ => return Ok(lhs),
            }
        }
    }

    fn parse_term(&mut self) -> Result<i64, String> {
        let mut lhs = self.parse_factor()?;
        loop {
            self.skip_ws();
            match self.peek() {
                Some(b'*') => {
                    self.pos += 1;
                    let rhs = self.parse_factor()?;
                    lhs = lhs.checked_mul(rhs).ok_or_else(|| "overflow".to_string())?;
                }
                Some(b'/') => {
                    self.pos += 1;
                    let rhs = self.parse_factor()?;
                    if rhs == 0 { return Err("division by zero".into()); }
                    lhs = lhs.checked_div(rhs).ok_or_else(|| "overflow".to_string())?;
                }
                Some(b'%') => {
                    self.pos += 1;
                    let rhs = self.parse_factor()?;
                    if rhs == 0 { return Err("division by zero".into()); }
                    lhs = lhs.checked_rem(rhs).ok_or_else(|| "overflow".to_string())?;
                }
                _ => return Ok(lhs),
            }
        }
    }

    fn parse_factor(&mut self) -> Result<i64, String> {
        self.skip_ws();
        match self.peek() {
            Some(b'-') => {
                self.pos += 1;
                let value = self.parse_factor()?;
                value.checked_neg().ok_or_else(|| "overflow".to_string())
            }
            Some(b'(') => {
                self.pos += 1;
                let value = self.parse_expr()?;
                self.skip_ws();
                if self.peek() != Some(b')') {
                    return Err(format!("expected ) at {}", self.pos));
                }
                self.pos += 1;
                Ok(value)
            }
            Some(b) if b.is_ascii_digit() => {
                let start = self.pos;
                while self.peek().map_or(false, |c| c.is_ascii_digit()) {
                    self.pos += 1;
                }
                let text = std::str::from_utf8(&self.bytes[start..self.pos]).unwrap();
                text.parse::<i64>().map_err(|_| "number out of range".to_string())
            }
            other => Err(format!(
                "unexpected character {:?} at {}",
                other.map(|b| b as char),
                self.pos
            )),
        }
    }
}

pub fn evaluate(input: &str) -> Result<i64, String> {
    let mut parser = Parser::new(input);
    let value = parser.parse_expr()?;
    parser.skip_ws();
    if parser.pos != parser.bytes.len() {
        return Err(format!("trailing input at {}", parser.pos));
    }
    Ok(value)
}
```

How each spec clause is met:

- **Precedence:** the expr → term → factor layering gives `*`, `/`, `%` higher precedence than `+`, `-`, and unary minus lives in factor so `-2 * 3` and `-(2 + 3)` both parse correctly; binary operators are left-associative because each level folds in a loop.
- **Overflow:** every operation goes through a `checked_*` method — including `checked_div`, which also catches the `i64::MIN / -1` corner — and `checked_neg` for negating `i64::MIN`. Nothing can panic or wrap.
- **Division by zero:** checked explicitly before dividing, with its own message distinct from overflow.
- **Positions:** errors for a missing `)`, an unexpected character, and trailing garbage all carry the byte position; a literal that doesn't fit in i64 is caught by the `parse::<i64>` failure and reported as out of range.

