use std::collections::HashMap;
use std::hash::Hash;

struct Entry<V> {
    value: V,
    freq: u64,
    last_used: u64,
}

pub struct LfuCache<K, V> {
    capacity: usize,
    tick: u64,
    entries: HashMap<K, Entry<V>>,
}

impl<K: Eq + Hash + Clone, V> LfuCache<K, V> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        LfuCache { capacity, tick: 0, entries: HashMap::new() }
    }

    pub fn get(&mut self, key: &K) -> Option<&V> {
        self.tick += 1;
        let tick = self.tick;
        let entry = self.entries.get_mut(key)?;
        entry.freq += 1;
        entry.last_used = tick;
        Some(&entry.value)
    }

    pub fn put(&mut self, key: K, value: V) {
        self.tick += 1;
        let tick = self.tick;
        if let Some(entry) = self.entries.get_mut(&key) {
            entry.value = value;
            entry.freq += 1;
            entry.last_used = tick;
            return;
        }
        if self.entries.len() >= self.capacity {
            let victim = self.entries.iter()
                .min_by_key(|(_, e)| (e.freq, e.last_used))
                .map(|(k, _)| k.clone())
                .unwrap();
            self.entries.remove(&victim);
        }
        self.entries.insert(key, Entry { value, freq: 1, last_used: tick });
    }

    pub fn len(&self) -> usize {
        self.entries.len()
    }
}
```

How each spec clause is met:

- **Eviction rule:** the victim is `min_by_key((freq, last_used))` — the tuple ordering makes lowest frequency primary and oldest use the tie-breaker, which is exactly the specified policy in one expression.
- **Uses counted uniformly:** both `get` and an updating `put` increment frequency and refresh `last_used`; a fresh insert starts at frequency 1.
- **Logical time:** the `tick` counter increments once per operation, so recency is a total order with no ties possible — two entries can never share a `last_used`, which keeps the tie-break deterministic.
- **Cost note:** eviction is an O(n) scan. That is the right trade for a spec-sized cache; a production LFU would keep per-frequency lists for O(1) operations at much higher complexity.

