#[derive(Debug)]
pub struct RingBuffer<T> {
    buf: Vec<Option<T>>,
    head: usize,   // index of oldest element
    len: usize,
}

impl<T> RingBuffer<T> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        let mut buf = Vec::with_capacity(capacity);
        buf.resize_with(capacity, || None);
        RingBuffer { buf, head: 0, len: 0 }
    }

    pub fn capacity(&self) -> usize { self.buf.len() }
    pub fn len(&self) -> usize { self.len }
    pub fn is_full(&self) -> bool { self.len == self.buf.len() }

    pub fn push(&mut self, item: T) {
        if self.is_full() {
            self.buf[self.head] = Some(item);
            self.head = (self.head + 1) % self.buf.len();
        } else {
            let tail = (self.head + self.len) % self.buf.len();
            self.buf[tail] = Some(item);
            self.len += 1;
        }
    }

    pub fn pop(&mut self) -> Option<T> {
        if self.len == 0 { return None; }
        let item = self.buf[self.head].take();
        self.head = (self.head + 1) % self.buf.len();
        self.len -= 1;
        item
    }

    pub fn to_vec(&self) -> Vec<&T> {
        (0..self.len)
            .map(|i| self.buf[(self.head + i) % self.buf.len()].as_ref().unwrap())
            .collect()
    }
}

fn main() {
    let mut ring = RingBuffer::new(3);
    for v in [1, 2, 3, 4] { ring.push(v); }
    println!("after push 1..4: {:?}", ring.to_vec());
    println!("pop: {:?}", ring.pop());
    ring.push(5);
    println!("after push 5: {:?}", ring.to_vec());
    println!("len: {}, full: {}", ring.len(), ring.is_full());
}

