pub fn insert_interval(intervals: &[(i64, i64)], new: (i64, i64)) -> Vec<(i64, i64)> {
    let mut result = Vec::new();
    let (mut start, mut end) = new;
    let mut inserted = false;
    for &(s, e) in intervals {
        if e + 1 < start {
            result.push((s, e));
        } else if end + 1 < s {
            if !inserted {
                result.push((start, end));
                inserted = true;
            }
            result.push((s, e));
        } else {
            start = start.min(s);
            end = end.max(e);
        }
    }
    if !inserted {
        result.push((start, end));
    }
    result
}

fn main() {
    let base = vec![(1, 2), (5, 8), (11, 13)];
    println!("{:?}", insert_interval(&base, (3, 10)));
    println!("{:?}", insert_interval(&[(1, 13)], (20, 22)));
    println!("{:?}", insert_interval(&[], (4, 6)));
}

