#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Version {
    pub major: u64,
    pub minor: u64,
    pub patch: u64,
    pub pre: Vec<String>,
}

impl Version {
    pub fn parse(text: &str) -> Result<Version, String> {
        let without_build = match text.split_once('+') {
            Some((head, _)) => head,
            None => text,
        };
        let (core, pre) = match without_build.split_once('-') {
            Some((core, pre)) => (
                core,
                pre.split('.').map(|s| s.to_string()).collect::<Vec<_>>(),
            ),
            None => (without_build, Vec::new()),
        };
        if pre.iter().any(|id| id.is_empty()) {
            return Err("empty prerelease identifier".into());
        }
        let parts: Vec<&str> = core.split('.').collect();
        if parts.len() != 3 {
            return Err("expected MAJOR.MINOR.PATCH".into());
        }
        let parse_num =
            |s: &str| s.parse::<u64>().map_err(|_| format!("invalid number {s:?}"));
        Ok(Version {
            major: parse_num(parts[0])?,
            minor: parse_num(parts[1])?,
            patch: parse_num(parts[2])?,
            pre,
        })
    }
}

fn cmp_pre(a: &[String], b: &[String]) -> std::cmp::Ordering {
    use std::cmp::Ordering::*;
    match (a.is_empty(), b.is_empty()) {
        (true, true) => Equal,
        (true, false) => Greater, // a release outranks its prereleases
        (false, true) => Less,
        (false, false) => {
            for (x, y) in a.iter().zip(b.iter()) {
                let ord = match (x.parse::<u64>(), y.parse::<u64>()) {
                    (Ok(m), Ok(n)) => m.cmp(&n),
                    (Ok(_), Err(_)) => Less, // numeric < alphanumeric
                    (Err(_), Ok(_)) => Greater,
                    (Err(_), Err(_)) => x.cmp(y),
                };
                if ord != Equal {
                    return ord;
                }
            }
            a.len().cmp(&b.len())
        }
    }
}

impl Ord for Version {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.major
            .cmp(&other.major)
            .then(self.minor.cmp(&other.minor))
            .then(self.patch.cmp(&other.patch))
            .then_with(|| cmp_pre(&self.pre, &other.pre))
    }
}

impl PartialOrd for Version {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}
```

How each spec clause is met:

- **Build metadata:** split off at the first `+` and discarded before anything else, so `1.0.0+build.5` and `1.0.0` parse to equal-precedence versions.
- **Prerelease precedence:** `cmp_pre` handles the four emptiness combinations first — crucially, an empty prerelease list means a *release*, which is Greater than any prerelease of the same core version.
- **Identifier rules:** the pairwise comparison tries parsing both sides as numbers; the mixed cases return Less/Greater so numeric identifiers always rank below alphanumeric ones, and two alphanumeric identifiers fall back to lexical order. If all shared identifiers are equal, the shorter list wins (is lower).
- **Validation:** exactly three core components, each a valid u64, and no empty prerelease identifiers — `1.0.0-alpha..1` and `1.0` are both Err.

