            (State::Locked, Event::Coin) => self.state = State::Unlocked,
            (State::Locked, Event::Push) => self.denied += 1,
            (State::Unlocked, Event::Push) => {
                self.state = State::Locked;
                self.entries += 1;
            }
            (State::Unlocked, Event::Coin) => self.spare_coins += 1,
        }
    }
}

