    let mut t = Turnstile::new();
    for event in [Event::Push, Event::Coin, Event::Push, Event::Coin, Event::Coin, Event::Push] {
        t.handle(event);
        println!("{event:?} -> {:?}", t.state());
    }
    println!("entries: {}, denied: {}, spare coins: {}", t.entries, t.denied, t.spare_coins);
