use std::collections::HashMap;

#[derive(Debug, PartialEq)]
pub struct Request {
    pub method: String,
    pub path: String,
    pub version: String,
    pub headers: HashMap<String, String>,
}

pub fn parse_request_head(raw: &str) -> Result<Request, String> {
    let mut lines = raw.lines();
    let request_line = lines.next().ok_or("empty request")?;
    let mut parts = request_line.split(' ');
    let method = parts.next().filter(|s| !s.is_empty()).ok_or("missing method")?;
    let path = parts.next().filter(|s| !s.is_empty()).ok_or("missing path")?;
    let version = parts
        .next()
        .filter(|s| s.starts_with("HTTP/"))
        .ok_or("missing version")?;
    if parts.next().is_some() {
        return Err("request line has too many parts".into());
    }
    let mut headers = HashMap::new();
    for line in lines {
        if line.is_empty() {
            break;
        }
        let (name, value) = line
            .split_once(':')
            .ok_or_else(|| format!("malformed header: {line:?}"))?;
        headers.insert(name.trim().to_lowercase(), value.trim().to_string());
    }
    Ok(Request {
        method: method.to_string(),
        path: path.to_string(),
        version: version.to_string(),
        headers,
    })
}
```

How each spec clause is met:

- **Request line arity:** exactly three space-separated parts are consumed and a fourth is an explicit error — a path containing a raw space (invalid HTTP, but a classic parser bug) fails loudly instead of being silently truncated.
- **Version check:** the third part must start with `HTTP/`, enforced in the same `filter` that extracts it, so `GET /x XYZ/1.1` is an Err, not a Request with a nonsense version.
- **Headers:** `split_once(':')` splits on the *first* colon only, so values containing colons (times, URLs with ports) survive intact; names are trimmed and lowercased before insertion, and HashMap insertion gives last-wins for repeats.
- **Blank line termination:** the loop breaks at the first empty line and never looks at the body — `str::lines` also handles both LF and CRLF endings, since it strips a trailing `\r`.

```rust
use std::time::Duration;

pub struct Backoff {
    base: Duration,
    max: Duration,
    factor: f64,
    current: Duration,
    remaining: Option<u32>,
}

impl Backoff {
    pub fn new(base: Duration, max: Duration, factor: f64, max_retries: Option<u32>) -> Self {
        Backoff { base, max, factor, current: base, remaining: max_retries }
    }

    pub fn reset(&mut self) {
        self.current = self.base;
    }
}

impl Iterator for Backoff {
    type Item = Duration;

    fn next(&mut self) -> Option<Duration> {
        if let Some(remaining) = self.remaining {
            if remaining == 0 {
                return None;
            }
            self.remaining = Some(remaining - 1);
        }
        let delay = self.current;
        self.current = self.current.mul_f64(self.factor).min(self.max);
        Some(delay)
    }
}
```

How each spec clause is met:

- **Sequence shape:** the current delay is yielded first and *then* advanced, so the first item is exactly `base` — the common bug of yielding base×factor first is avoided.
- **Overflow safety:** the running value is clamped to `max` after every multiplication, so it can never grow past max no matter how many items are drawn; `mul_f64` on a bounded Duration stays in range.
- **Budget semantics:** `remaining` decrements only when an item is actually produced, and `reset()` deliberately touches only `current` — a caller that resets after a success starts the delay curve over without regaining retry budget, exactly as specified.
- **Iterator protocol:** with no budget (`None`), the iterator is infinite, which composes correctly with `.take(n)` and `zip` in caller code.

