```kotlin
sealed interface BuyResult {
    data class Success(val item: String, val change: Map<Int, Int>) : BuyResult
    data class InsufficientFunds(val neededCents: Int) : BuyResult
    object OutOfStock : BuyResult
    object CannotMakeChange : BuyResult
    object UnknownItem : BuyResult
}

class VendingMachine(
    private val prices: Map<String, Int>,
    stock: Map<String, Int>,
    float: Map<Int, Int>,
) {
    private val stock = stock.toMutableMap()
    private val coinBox = float.toMutableMap()   // denomination -> count
    private var balance = 0
    private val inserted = mutableMapOf<Int, Int>()

    fun insertCoin(denom: Int) {
        require(denom in setOf(5, 10, 25, 100)) { "unknown coin: $denom" }
        balance += denom
        inserted[denom] = (inserted[denom] ?: 0) + 1
    }

    fun cancel(): Map<Int, Int> {
        val refund = inserted.toMap()
        inserted.clear()
        balance = 0
        return refund
    }

    fun select(item: String): BuyResult {
        val price = prices[item] ?: return BuyResult.UnknownItem
        if ((stock[item] ?: 0) == 0) return BuyResult.OutOfStock
        if (balance < price) return BuyResult.InsufficientFunds(price - balance)
        val changeDue = balance - price
        // Coins available for change: the float plus what this customer inserted.
        val available = (coinBox.keys + inserted.keys).associateWith {
            (coinBox[it] ?: 0) + (inserted[it] ?: 0)
        }.toMutableMap()
        val change = mutableMapOf<Int, Int>()
        var remaining = changeDue
        for (denom in available.keys.sortedDescending()) {
            val use = minOf(remaining / denom, available.getValue(denom))
            if (use > 0) {
                change[denom] = use
                available[denom] = available.getValue(denom) - use
                remaining -= use * denom
            }
        }
        if (remaining != 0) return BuyResult.CannotMakeChange
        // Commit only once change is known to be makeable.
        coinBox.clear()
        coinBox.putAll(available.filterValues { it > 0 })
        stock[item] = stock.getValue(item) - 1
        inserted.clear()
        balance = 0
        return BuyResult.Success(item, change)
    }
}
```

How each spec clause is met:

- **Check order:** unknown item, stock, then funds, then change — a customer short on money hears about the shortfall even if the machine also couldn't make change, and no check mutates anything.
- **Change pool:** `available` merges the float with the inserted coins before the greedy pass, which matters — a customer who inserts a 100 for a 75-cent item can receive their own quarters back as change.
- **Atomic abort:** the greedy computation runs entirely on a scratch map; `coinBox`, stock, and balance are only touched in the commit block after `remaining == 0` is proven. CannotMakeChange therefore leaves the machine exactly as it was, and the customer can still `cancel()` for a full refund of the actual inserted coins.
- **Cancel fidelity:** refunds come from the `inserted` map (the literal coins), not from an equivalent-value computation, so a customer never gets different denominations back on a cancel.

```kotlin
fun globMatches(text: String, pattern: String): Boolean {
    // dp[i][j] = text prefix of length i matches pattern prefix of length j
    val dp = Array(text.length + 1) { BooleanArray(pattern.length + 1) }
    dp[0][0] = true
    for (j in 1..pattern.length) {
        if (pattern[j - 1] == '*') dp[0][j] = dp[0][j - 1]
    }
    for (i in 1..text.length) {
        for (j in 1..pattern.length) {
            dp[i][j] = when (pattern[j - 1]) {
                '*' -> dp[i][j - 1] || dp[i - 1][j]
                '?', text[i - 1] -> dp[i - 1][j - 1]
                else -> false
            }
        }
    }
    return dp[text.length][pattern.length]
}
```

How each spec clause is met:

- **Star semantics:** `dp[i][j - 1] || dp[i - 1][j]` is the whole rule — the star either consumes nothing (move past it in the pattern) or consumes one more text character (stay on the star). Both branches are needed; dropping the first is the classic bug that makes `*` require at least one character.
- **Empty-text row:** the pre-loop fills dp[0][j] for leading stars, so a pattern like `**a` correctly fails against empty text (the `a` can never match) while `***` succeeds.
- **? and literals share a branch:** both consume exactly one character diagonally; the comma-condition in the `when` treats `?` as matching any single text character and a literal as matching only itself.
- **Complexity:** O(n·m) time and space, with no recursion — pathological patterns like `*a*a*a*b` against long strings can't blow a stack or backtrack exponentially the way a naive recursive matcher does.

