fun maxConcurrent(intervals: List<Pair<Int, Int>>): Int {
    val events = mutableListOf<Pair<Int, Int>>()  // (time, delta)
    for ((start, end) in intervals) {
        if (end <= start) continue
        events.add(start to 1)
        events.add(end to -1)
    }
    events.sortWith(compareBy({ it.first }, { it.second }))
    var current = 0
    var best = 0
    for ((_, delta) in events) {
        current += delta
        if (current > best) best = current
    }
    return best
}

fun main() {
    val bookings = listOf(540 to 660, 600 to 720, 660 to 780, 615 to 645, 700 to 800)
    println("max concurrent: ${maxConcurrent(bookings)}")
    println("empty: ${maxConcurrent(emptyList())}")
    println("back to back: ${maxConcurrent(listOf(0 to 60, 60 to 120))}")
}

