data class PasswordPolicy(
    val minLength: Int = 10,
    val requireUpper: Boolean = true,
    val requireLower: Boolean = true,
    val requireDigit: Boolean = true,
    val requireSymbol: Boolean = true,
    val blocklist: Set<String> = emptySet(),
)

fun validatePassword(password: String, policy: PasswordPolicy): List<String> {
    val problems = mutableListOf<String>()
    if (password.length < policy.minLength) {
        problems += "must be at least ${policy.minLength} characters"
    }
    if (password.any { it.isWhitespace() }) {
        problems += "must not contain whitespace"
    }
    if (policy.requireUpper && password.none { it.isUpperCase() }) {
        problems += "must contain an uppercase letter"
    }
    if (policy.requireLower && password.none { it.isLowerCase() }) {
        problems += "must contain a lowercase letter"
    }
    if (policy.requireDigit && password.none { it.isDigit() }) {
        problems += "must contain a digit"
    }
    if (policy.requireSymbol && password.none { !it.isLetterOrDigit() }) {
        problems += "must contain a symbol"
    }
    if (policy.blocklist.any { it.equals(password, ignoreCase = true) }) {
        problems += "is on the blocklist"
    }
    return problems
}
```

How each spec clause is met:

- **Fixed order:** the checks are written in exactly the specified sequence and each appends independently, so the output order is stable and testable — a UI can display the list verbatim.
- **Flags gate only their own rule:** the whitespace check sits outside the flag-gated group, as specified; disabling requireSymbol never disables the whitespace rule.
- **Symbol definition:** a symbol is any character that is not a letter or digit — this deliberately counts punctuation and also spaces, though a space will already have produced the whitespace violation; both messages can legitimately appear.
- **Blocklist:** `equals(..., ignoreCase = true)` against every entry, so "Password1!" is caught by a blocklist entry "password1!".

