import java.io.IOException

data class HttpResponse<T>(val status: Int, val body: T?, val retryAfterSeconds: Long? = null)

private val RETRYABLE_STATUSES = setOf(408, 429, 500, 502, 503, 504)
private val IDEMPOTENT_METHODS = setOf("GET", "HEAD", "PUT", "DELETE")

fun <T> executeWithRetry(
    method: String,
    hasIdempotencyKey: Boolean,
    maxAttempts: Int,
    baseDelayMs: Long,
    sleeper: (Long) -> Unit,
    call: () -> HttpResponse<T>,
): HttpResponse<T> {
    require(maxAttempts >= 1) { "maxAttempts must be >= 1" }
    val mayRetry = method.uppercase() in IDEMPOTENT_METHODS || hasIdempotencyKey
    var attempt = 0
    while (true) {
        attempt++
        try {
            val response = call()
            if (!mayRetry || response.status !in RETRYABLE_STATUSES || attempt >= maxAttempts) {
                return response
            }
            val delay = response.retryAfterSeconds?.times(1000)
                ?: minOf(baseDelayMs * (1L shl (attempt - 1)), 30_000L)
            sleeper(delay)
        } catch (e: IOException) {
            if (!mayRetry || attempt >= maxAttempts) throw e
            sleeper(minOf(baseDelayMs * (1L shl (attempt - 1)), 30_000L))
        }
    }
}
```

How each spec clause is met:

- **Permission gate first:** `mayRetry` is computed once from the method and idempotency key; a POST without a key returns even a 503 immediately, and its IOExceptions propagate — the executor never silently repeats a non-idempotent operation.
- **One return path per outcome:** the status branch returns the response when retries are disallowed, unneeded, or exhausted — so "return the last response" and "return success immediately" are the same line, with no chance of an extra attempt.
- **Retry-After precedence:** the Elvis chain prefers the server's explicit delay (converted to ms) and only falls back to capped exponential backoff; note Retry-After is *not* capped at 30s — the cap applies to our own backoff, while a server instruction is honored as given.
- **Sleeper injection:** delays are handed to the caller's lambda, so tests record the exact delay sequence [base, 2*base, ...] with zero real waiting.

