class TwoStackDeque<T> {
    private var front = ArrayDeque<T>()  // top (last) = front of the deque
    private var back = ArrayDeque<T>()   // top (last) = back of the deque

    val size: Int get() = front.size + back.size
    fun isEmpty(): Boolean = size == 0

    fun pushFront(item: T) = front.addLast(item)
    fun pushBack(item: T) = back.addLast(item)

    fun peekFront(): T? {
        rebalanceIfNeeded(fromFront = true)
        return front.lastOrNull()
    }

    fun peekBack(): T? {
        rebalanceIfNeeded(fromFront = false)
        return back.lastOrNull()
    }

    fun popFront(): T? {
        rebalanceIfNeeded(fromFront = true)
        return if (front.isEmpty()) null else front.removeLast()
    }

    fun popBack(): T? {
        rebalanceIfNeeded(fromFront = false)
        return if (back.isEmpty()) null else back.removeLast()
    }

    private fun rebalanceIfNeeded(fromFront: Boolean) {
        if (fromFront && front.isEmpty() && back.isNotEmpty()) {
            // Drain back (its top is the deque's back) into deque order.
            val all = generateSequence { if (back.isEmpty()) null else back.removeLast() }
                .toList().reversed()
            val half = (all.size + 1) / 2
            for (item in all.subList(0, half).reversed()) front.addLast(item)
            for (item in all.subList(half, all.size)) back.addLast(item)
        } else if (!fromFront && back.isEmpty() && front.isNotEmpty()) {
            // Drain front (its top is the deque's front): already in deque order.
            val all = generateSequence { if (front.isEmpty()) null else front.removeLast() }
                .toList()
            val half = (all.size + 1) / 2
            for (item in all.subList(0, half).reversed()) front.addLast(item)
            for (item in all.subList(half, all.size)) back.addLast(item)
        }
    }
}
```

How each spec clause is met:

- **Half-split rebalancing:** when one side is empty, the other side's elements are listed in deque order and split — the front half goes to the front stack (pushed in reverse so its top is the deque's front element) and the back half returns to the back stack. Each element moves O(1) times per halving, which is what makes pops amortized O(1) even under alternating popFront/popBack.
- **Why not move-all:** with move-all, pushBack × n followed by alternating pops forces a full transfer per pop — O(n) each. Halving guarantees at least half the elements stay put, so a transfer of k elements is paid for by k/2 subsequent cheap pops.
- **Orientation discipline:** both stacks keep their top at the deque's outer end; the two rebalance branches differ only in whether draining produces deque order directly (from front) or reversed (from back), and both then rebuild with the same code.
- **Peeks rebalance too:** a peek at an empty side triggers the same rebalance as a pop, so peek is also amortized O(1) rather than O(n) worst-case per call.

