```kotlin
class JsonParseException(message: String) : Exception(message)

class FlatJsonParser(private val text: String) {
    private var pos = 0

    fun parse(): Map<String, Any?> {
        val result = LinkedHashMap<String, Any?>()
        skipWs()
        expect('{')
        skipWs()
        if (peek() == '}') {
            pos++
            finish()
            return result
        }
        while (true) {
            skipWs()
            val key = parseString()
            skipWs()
            expect(':')
            skipWs()
            result[key] = parseValue()
            skipWs()
            when (next()) {
                ',' -> continue
                '}' -> {
                    finish()
                    return result
                }
                else -> throw JsonParseException("expected , or } at $pos")
            }
        }
    }

    private fun parseValue(): Any? {
        return when (peek()) {
            '"' -> parseString()
            't' -> { expectWord("true"); true }
            'f' -> { expectWord("false"); false }
            'n' -> { expectWord("null"); null }
            '-', in '0'..'9' -> parseNumber()
            else -> throw JsonParseException("unsupported value at $pos (flat objects only)")
        }
    }

    private fun parseNumber(): Long {
        val start = pos
        if (peek() == '-') pos++
        while (pos < text.length && text[pos].isDigit()) pos++
        if (pos < text.length && (text[pos] == '.' || text[pos] == 'e' || text[pos] == 'E')) {
            throw JsonParseException("only integers are supported at $start")
        }
        return text.substring(start, pos).toLongOrNull()
            ?: throw JsonParseException("invalid number at $start")
    }

    private fun parseString(): String {
        expect('"')
        val sb = StringBuilder()
        while (true) {
            if (pos >= text.length) throw JsonParseException("unterminated string")
            when (val ch = text[pos++]) {
                '"' -> return sb.toString()
                '\\' -> {
                    if (pos >= text.length) throw JsonParseException("unterminated escape")
                    when (val esc = text[pos++]) {
                        '"' -> sb.append('"')
                        '\\' -> sb.append('\\')
                        '/' -> sb.append('/')
                        'n' -> sb.append('\n')
                        't' -> sb.append('\t')
                        'r' -> sb.append('\r')
                        'b' -> sb.append('\b')
                        'f' -> sb.append('\u000C')
                        'u' -> {
                            if (pos + 4 > text.length) throw JsonParseException("bad unicode escape")
                            val code = text.substring(pos, pos + 4).toIntOrNull(16)
                                ?: throw JsonParseException("bad unicode escape")
                            sb.append(code.toChar())
                            pos += 4
                        }
                        else -> throw JsonParseException("unknown escape \\$esc")
                    }
                }
                else -> sb.append(ch)
            }
        }
    }

    private fun expectWord(word: String) {
        if (!text.startsWith(word, pos)) throw JsonParseException("expected $word at $pos")
        pos += word.length
    }

    private fun skipWs() { while (pos < text.length && text[pos].isWhitespace()) pos++ }
    private fun peek(): Char = if (pos < text.length) text[pos] else '\u0000'
    private fun next(): Char = if (pos < text.length) text[pos++] else '\u0000'
    private fun expect(ch: Char) {
        if (next() != ch) throw JsonParseException("expected '$ch' at $pos")
    }
    private fun finish() {
        skipWs()
        if (pos != text.length) throw JsonParseException("trailing content at $pos")
    }
}

fun parseFlatJson(text: String): Map<String, Any?> = FlatJsonParser(text).parse()
```

How each spec clause is met:

- **Flatness enforced at the value dispatcher:** `{` or `[` as a value start falls into the `else` branch and throws — the parser has no code path that could recurse into a nested structure.
- **Integers only:** parseNumber consumes digits (and a leading minus), then explicitly rejects a following `.`, `e`, or `E`, so `1.5` is a clear \"only integers\" error rather than a silently truncated 1.
- **Positions everywhere:** every throw includes `pos` or the token's start, and `peek()` returns a NUL sentinel past the end so truncated input produces JsonParseException instead of an index crash.
- **Duplicate keys:** plain assignment into the LinkedHashMap gives last-wins values while keeping first-insertion key order.

