struct RGBAColor {
    let red: Double
    let green: Double
    let blue: Double
    let alpha: Double
}

func parseHexColor(_ text: String) -> RGBAColor? {
    var hex = text.hasPrefix("#") ? String(text.dropFirst()) : text
    guard [3, 6, 8].contains(hex.count) else { return nil }
    if hex.count == 3 {
        hex = hex.map { "\($0)\($0)" }.joined()
    }
    var components: [Double] = []
    var index = hex.startIndex
    while index < hex.endIndex {
        let next = hex.index(index, offsetBy: 2)
        guard let byte = UInt8(hex[index..<next], radix: 16) else { return nil }
        components.append(Double(byte) / 255.0)
        index = next
    }
    return RGBAColor(
        red: components[0],
        green: components[1],
        blue: components[2],
        alpha: components.count == 4 ? components[3] : 1.0
    )
}
```

How each spec clause is met:

- **Length gate first:** only 3, 6, or 8 hex digits proceed — strings like "#12345" are rejected before any parsing, so no partial color can leak through.
- **Nibble expansion:** the 3-digit form is rewritten by duplicating each character ("F0A" -> "FF00AA") *before* the byte loop, so one code path handles all three formats and the expansion rule lives in exactly one place.
- **Per-byte validation:** each pair is parsed with `UInt8(_, radix: 16)`, which returns nil for non-hex characters — the guard turns that into a nil result for the whole color rather than a trapped crash or a defaulted channel.
- **Alpha position:** in the 8-digit form the alpha is the *last* byte (RRGGBBAA), matching CSS Color 4; the components array makes that ordering explicit instead of relying on bit-shifting an integer, where AARRGGBB vs RRGGBBAA mistakes are common.

