final class FifoTTLCache<Key: Hashable, Value> {
    private struct Entry {
        var value: Value
        var expiresAt: Int
    }

    private let capacity: Int
    private var entries: [Key: Entry] = [:]
    private var order: [Key] = []   // insertion order, oldest first

    init(capacity: Int) {
        precondition(capacity > 0, "capacity must be positive")
        self.capacity = capacity
    }

    func get(_ key: Key, now: Int) -> Value? {
        guard let entry = entries[key] else { return nil }
        if entry.expiresAt <= now {
            remove(key)
            return nil
        }
        return entry.value
    }

    func set(_ key: Key, value: Value, ttl: Int, now: Int) {
        purgeExpired(now: now)
        if entries[key] == nil {
            order.append(key)
        }
        entries[key] = Entry(value: value, expiresAt: now + ttl)
        while entries.count > capacity {
            let victim = order.removeFirst()
            entries.removeValue(forKey: victim)
        }
    }

    private func purgeExpired(now: Int) {
        for key in order where (entries[key]?.expiresAt ?? Int.max) <= now {
            entries.removeValue(forKey: key)
        }
        order.removeAll { entries[$0] == nil }
    }

    private func remove(_ key: Key) {
        entries.removeValue(forKey: key)
        order.removeAll { $0 == key }
    }
}

