func compress(_ s: String) -> String {
    let chars = Array(s)
    guard !chars.isEmpty else { return s }
    var out = ""
    var runChar = chars[0]
    var runCount = 1
    for ch in chars.dropFirst() {
        if ch == runChar {
            runCount += 1
        } else {
            out += "\(runChar)\(runCount)"
            runChar = ch
            runCount = 1
        }
    }
    out += "\(runChar)\(runCount)"
    return out.count < s.count ? out : s
