final class LeakyBucket {
    private let capacity: Double
    private let leakRatePerSecond: Double
    private var level: Double = 0
    private var lastTime: Double

    init(capacity: Double, leakRatePerSecond: Double, now: Double) {
        precondition(capacity > 0 && leakRatePerSecond > 0, "capacity and rate must be positive")
        self.capacity = capacity
        self.leakRatePerSecond = leakRatePerSecond
        self.lastTime = now
    }

    private func drain(to now: Double) {
        let elapsed = max(0, now - lastTime)
        level = max(0, level - elapsed * leakRatePerSecond)
        lastTime = now
    }

    func currentLevel(now: Double) -> Double {
        drain(to: now)
        return level
    }

    @discardableResult
    func pour(_ amount: Double, now: Double) -> Bool {
        drain(to: now)
        guard amount >= 0, level + amount <= capacity else { return false }
        level += amount
        return true
    }
}
```

How each spec clause is met:

- **Lazy draining:** there is no timer — the level is brought up to date at the start of every public call from the elapsed time since the last call, which is why the caller-supplied `now` is sufficient and tests are fully deterministic.
- **All-or-nothing pours:** the guard checks the *post-drain* level plus the full amount against capacity before any mutation, so a rejected pour leaves the level untouched (no partial fills).
- **Floor at zero:** `max(0, ...)` in drain means a long idle period empties the bucket exactly, never making it negative — a negative level would silently grant extra capacity later.
- **Clock regression:** `max(0, now - lastTime)` treats a backwards timestamp as zero elapsed rather than *adding* level back, the safe failure direction for a rate limiter.

```swift
struct BloomFilter {
    private var bits: [Bool]
    private let hashCount: Int

    init(bitCount: Int, hashCount: Int) {
        precondition(bitCount > 0 && hashCount > 0, "bitCount and hashCount must be positive")
        bits = [Bool](repeating: false, count: bitCount)
        self.hashCount = hashCount
    }

    private func fnv(_ s: String, seed: UInt64) -> UInt64 {
        var hash: UInt64 = seed
        for byte in s.utf8 {
            hash ^= UInt64(byte)
            hash &*= 0x100000001b3
        }
        return hash
    }

    private func indices(for s: String) -> [Int] {
        let h1 = fnv(s, seed: 0xcbf29ce484222325)
        let h2 = fnv(s, seed: 0x84222325cbf29ce4) | 1   // odd step
        return (0..<hashCount).map { i in
            Int((h1 &+ UInt64(i) &* h2) % UInt64(bits.count))
        }
    }

    mutating func insert(_ s: String) {
        for index in indices(for: s) {
            bits[index] = true
        }
    }

    func contains(_ s: String) -> Bool {
        indices(for: s).allSatisfy { bits[$0] }
    }
}
```

How each spec clause is met:

- **No false negatives:** `insert` sets exactly the bits that `contains` checks, and bits are never cleared (there is no delete), so anything inserted always reports present. False positives arise only when other strings happen to cover all k bits.
- **Double hashing:** two FNV-1a passes with different offset bases give independent h1 and h2; the k indices are h1 + i·h2, the Kirsch–Mitzenmacher construction, which behaves like k independent hashes. Forcing h2 odd guarantees the step is coprime with any power-of-two bit count, so the sequence doesn't collapse onto a short cycle.
- **Overflow discipline:** the multiply in FNV uses `&*` (wrapping) deliberately — overflow is part of the hash's mixing, and a trapping multiply would crash on ordinary input.
- **Value semantics:** the filter is a struct with a mutating insert, so copies are independent — a snapshot copy taken before more inserts won't change under the caller's feet.

