func firstFreeSlot(events: [(Int, Int)], dayStart: Int, dayEnd: Int, duration: Int) -> (Int, Int)? {
    let sorted = events
        .map { (max($0.0, dayStart), min($0.1, dayEnd)) }
        .filter { $0.1 > $0.0 }
        .sorted { $0.0 < $1.0 }
    var cursor = dayStart
    for (start, end) in sorted {
        if start - cursor >= duration {
            return (cursor, cursor + duration)
        }
        cursor = max(cursor, end)
    }
    if dayEnd - cursor >= duration {
        return (cursor, cursor + duration)
    }
    return nil
}

