func validateProfile(_ input: ProfileInput) -> Result<Profile, ValidationErrors> {
    var errors: [String] = []
    let name = input.name.trimmingCharacters(in: .whitespaces)
    if name.isEmpty {
        errors.append("name must not be empty")
    } else if name.count > 60 {
        errors.append("name must be at most 60 characters")
