    if !(0...130).contains(input.age) {
        errors.append("age must be between 0 and 130")
    }
    let parts = input.email.split(separator: "@", omittingEmptySubsequences: false)
    if parts.count != 2 || parts[0].isEmpty || !parts[1].contains(".") {
        errors.append("email must look like name@domain.tld")
    }
    guard errors.isEmpty else {
        return .failure(ValidationErrors(messages: errors))
    }
    return .success(Profile(name: name, age: input.age, email: input.email))
}
