    var index = 0
    var reduces: [Int] = []
    while true {
        let state = states.last!
        let token = input[index]
        guard let act = action["\(state),\(token)"] else {
            throw ParseError.noAction(state: state, token: token)
        }
        if act == "acc" {
            return reduces
        } else if act.hasPrefix("s") {
            states.append(Int(act.dropFirst())!)
            index += 1
        } else if act.hasPrefix("r") {
            let number = Int(act.dropFirst())!
            let production = productions[number]
            for _ in 0..<production.rhsCount {
                states.removeLast()
            }
            let exposed = states.last!
            guard let nextState = goto["\(exposed),\(production.lhs)"] else {
                throw ParseError.noGoto(state: exposed, symbol: production.lhs)
            }
            states.append(nextState)
            reduces.append(number)
        }
    }
}
```

How each spec clause is met:

- **State-only stack:** the loop keeps just the state stack (symbols are implicit — the state encodes them), which is the standard memory-frugal form; shifts push the table's target state and consume a token, reduces never consume input.
- **Reduce mechanics:** popping `rhsCount` states exposes the state that preceded the handle; the goto lookup from that exposed state on the production's LHS gives the state to push. Getting either lookup wrong is the classic LR bug, so both are guarded with distinct error cases rather than force-unwrapped.
- **Reduce recording:** production numbers append in the order reductions fire, so for tokens num + num * num the returned list reads as the rightmost derivation in reverse — the expected shape for a bottom-up parse.
- **Termination:** "acc" returns; every other step either consumes a token or reduces, and a missing entry throws, so malformed input can't spin the loop forever on a well-formed table.

