enum BreakerResult<T> {
    case success(T)
    case failure(Error)
    case rejected
}

final class CircuitBreaker {
    private let failureThreshold: Int
    private let resetTimeout: Double
    private var consecutiveFailures = 0
    private var openedAt: Double?

    init(failureThreshold: Int, resetTimeout: Double) {
        precondition(failureThreshold > 0 && resetTimeout >= 0, "invalid breaker configuration")
        self.failureThreshold = failureThreshold
        self.resetTimeout = resetTimeout
    }

    var isOpen: Bool { openedAt != nil }

    func call<T>(now: Double, operation: () throws -> T) -> BreakerResult<T> {
        if let opened = openedAt, now - opened < resetTimeout {
            return .rejected
        }
        // Closed, or open-but-timeout-elapsed (half-open trial).
        do {
            let value = try operation()
            consecutiveFailures = 0
            openedAt = nil
            return .success(value)
        } catch {
            consecutiveFailures += 1
            if openedAt != nil || consecutiveFailures >= failureThreshold {
                openedAt = now
            }
            return .failure(error)
        }
    }
}
```

How each spec clause is met:

- **One code path for closed and half-open:** the guard only short-circuits when the circuit is open *and* the timeout hasn't elapsed; everything else runs the operation, and the outcome handlers encode the difference — success always closes and resets (correct for both states), while failure re-opens immediately if this was a trial (`openedAt != nil`) or opens on reaching the threshold in closed state.
- **Rejection is side-effect free:** the rejected branch returns before `operation` is invoked — the protected service sees zero traffic while the circuit is open, which is the entire point of the pattern.
- **Consecutive, not cumulative:** a success in closed state zeroes the counter, so failures separated by successes never accumulate toward the threshold.
- **Half-open failure timing:** re-opening stamps `openedAt = now` (the trial's time), so the full timeout must elapse again before the next trial — the breaker doesn't leak repeated trials on a still-dead dependency.

