class InsufficientFundsError < StandardError; end

class Account
  attr_reader :balance

  def initialize(opening_cents)
    raise ArgumentError, "opening balance must be >= 0" if opening_cents.negative?

    @balance = opening_cents
    @history = []
  end

  def deposit(cents)
    validate_positive!(cents)
    @balance += cents
    record(:deposit, cents)
    @balance
  end

  def withdraw(cents)
    validate_positive!(cents)
    raise InsufficientFundsError, "need #{cents}, have #{@balance}" if cents > @balance

    @balance -= cents
    record(:withdraw, cents)
    @balance
  end

  def transfer_to(other, cents)
    validate_positive!(cents)
    raise InsufficientFundsError, "need #{cents}, have #{@balance}" if cents > @balance

    @balance -= cents
    record(:transfer_out, cents)
    other.receive_transfer(cents)
    @balance
  end

  def history
    @history.dup
  end

  protected

  def receive_transfer(cents)
    @balance += cents
    record(:transfer_in, cents)
  end

  private

  def validate_positive!(cents)
    raise ArgumentError, "amount must be positive" unless cents.is_a?(Integer) && cents.positive?
  end

  def record(type, amount)
    @history << { type: type, amount: amount, balance_after: @balance }.freeze
  end
end
```

How each spec clause is met:

- **Atomic transfer:** both validations (positive amount, sufficient funds) run *before* any mutation, and the receiving side's `receive_transfer` cannot fail — it only adds a positive, already-validated amount. So once the debit happens, the credit is guaranteed, and on any validation failure neither balance nor either history has been touched.
- **Protected, not public:** `receive_transfer` is `protected`, meaning only Account instances can invoke it on each other — outside code can't fabricate a transfer_in credit without a matching debit.
- **History integrity:** entries are frozen at creation, and `history` returns a `dup` of the array, so callers can neither rewrite a recorded entry nor append fake ones to the ledger. `balance_after` inside each entry makes the history self-auditing: replaying amounts must reproduce every recorded balance.
- **Insufficient funds is side-effect free:** the raise happens before `@balance -= cents` and before `record`, so a failed withdrawal is invisible in both the balance and the history — exactly what the spec requires.

