interface Scheduler {
  schedule(fn: () => void, ms: number): unknown;
  cancel(handle: unknown): void;
}

class ManualScheduler implements Scheduler {
  private now = 0;
  private nextId = 1;
  private timers: { id: number; at: number; fn: () => void }[] = [];

  schedule(fn: () => void, ms: number): unknown {
    const id = this.nextId++;
    this.timers.push({ id, at: this.now + ms, fn });
    return id;
  }

  cancel(handle: unknown): void {
    this.timers = this.timers.filter((t) => t.id !== handle);
  }

  advance(ms: number): void {
    const target = this.now + ms;
    while (true) {
      const due = this.timers
        .filter((t) => t.at <= target)
        .sort((a, b) => a.at - b.at || a.id - b.id)[0];
      if (!due) break;
      this.timers = this.timers.filter((t) => t.id !== due.id);
      this.now = due.at;
      due.fn();
    }
    this.now = target;
  }
}

function debounce<A extends unknown[]>(
  fn: (...args: A) => void,
  waitMs: number,
  scheduler: Scheduler,
): (...args: A) => void {
  let handle: unknown = null;
  return (...args: A) => {
    if (handle !== null) scheduler.cancel(handle);
    handle = scheduler.schedule(() => {
      handle = null;
      fn(...args);
    }, waitMs);
  };
}

function throttle<A extends unknown[]>(
  fn: (...args: A) => void,
  waitMs: number,
  scheduler: Scheduler,
): (...args: A) => void {
  let coolingDown = false;
  return (...args: A) => {
    if (coolingDown) return;
    fn(...args);
    coolingDown = true;
    scheduler.schedule(() => {
      coolingDown = false;
    }, waitMs);
  };
}

const scheduler = new ManualScheduler();
const log: string[] = [];
const debounced = debounce((label: string) => log.push(`debounced ${label}`), 200, scheduler);
const throttled = throttle((label: string) => log.push(`throttled ${label}`), 200, scheduler);

debounced("a");
throttled("a");
scheduler.advance(100);
debounced("b");
throttled("b");
scheduler.advance(150);
debounced("c");
scheduler.advance(50);
throttled("c");
scheduler.advance(200);
