function runPool<T>(tasks: (() => Promise<T>)[], limit: number): Promise<T[]> {
  if (limit < 1) throw new Error("limit must be >= 1");
  const results: T[] = new Array(tasks.length);
  let nextIndex = 0;
  let failed = false;

  async function worker(): Promise<void> {
    while (!failed && nextIndex < tasks.length) {
      const index = nextIndex++;
      try {
        results[index] = await tasks[index]();
      } catch (error) {
        failed = true;
        throw error;
      }
    }
  }

  const workers = Array.from({ length: Math.min(limit, tasks.length) }, () => worker());
  return Promise.all(workers).then(() => results);
}

let active = 0;
let peak = 0;
const tick = () => Promise.resolve();

function makeTask(id: number, ticks: number): () => Promise<number> {
  return async () => {
    active++;
    peak = Math.max(peak, active);
    for (let i = 0; i < ticks; i++) await tick();
    active--;
    return id * 10;
  };
}

const tasks = [makeTask(0, 3), makeTask(1, 1), makeTask(2, 2), makeTask(3, 1), makeTask(4, 2), makeTask(5, 1)];
runPool(tasks, 2).then((results) => {
  console.log("results:", JSON.stringify(results));
  console.log("peak concurrency:", peak);
});

