interface User {
  id: number;
  name: string;
  email: string;
  tags: string[];
}

function parseUser(value: unknown): User {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    throw new TypeError("user must be an object");
  }
  const record = value as Record<string, unknown>;

  const id = record.id;
  if (typeof id !== "number" || !Number.isInteger(id) || id <= 0) {
    throw new TypeError("user.id must be a positive integer");
  }

  const name = record.name;
  if (typeof name !== "string" || name.trim().length === 0) {
    throw new TypeError("user.name must be a non-empty string");
  }

  const email = record.email;
  if (typeof email !== "string") {
    throw new TypeError("user.email must be a string");
  }
  const emailParts = email.split("@");
  if (emailParts.length !== 2 || emailParts[0].length === 0 || emailParts[1].length === 0) {
    throw new TypeError("user.email must contain exactly one @ with non-empty parts");
  }

  let tags: string[] = [];
  if (record.tags !== undefined) {
    if (!Array.isArray(record.tags) || !record.tags.every((t) => typeof t === "string")) {
      throw new TypeError("user.tags must be an array of strings");
    }
    tags = [...new Set(record.tags as string[])];
  }

  return { id, name: name.trim(), email, tags };
}
```

How each spec clause is met:

- **Narrowing cascade:** each field is read as `unknown` and checked with typeof/Number guards before use — after each guard, TypeScript itself narrows the type, so the returned object is built only from values proven to have the right shape. No `as` cast touches unvalidated data except the initial record view, which is only used for property access.
- **Object check done properly:** `typeof null === "object"` and arrays are objects too, so both are excluded explicitly — the three-part guard is the standard correct form.
- **Tags semantics:** absent (undefined) defaults to []; present-but-wrong-type throws; duplicates are removed via Set while preserving first-occurrence order. Note `null` counts as present-and-wrong, not absent — a deliberate distinction, since JSON null is a value the sender chose.
- **Failures name the field:** every TypeError message is prefixed with the field path ("user.email ..."), so an API layer can surface it directly to the client.

