class LruTtlCache<K, V> {
  private entries = new Map<K, { value: V; expiresAt: number }>();

  constructor(
    private maxSize: number,
    private ttlMs: number,
    private now: () => number,
  ) {
    if (maxSize <= 0 || ttlMs <= 0) {
      throw new Error("maxSize and ttlMs must be positive");
    }
  }

  private purgeExpired(): void {
    const t = this.now();
    for (const [key, entry] of this.entries) {
      if (entry.expiresAt <= t) {
        this.entries.delete(key);
      }
    }
  }

  get(key: K): V | undefined {
    const entry = this.entries.get(key);
    if (!entry) return undefined;
    if (entry.expiresAt <= this.now()) {
      this.entries.delete(key);
      return undefined;
    }
    // Refresh recency: re-insert at the tail.
    this.entries.delete(key);
    this.entries.set(key, entry);
    return entry.value;
  }

  set(key: K, value: V): void {
    this.purgeExpired();
    this.entries.delete(key);
    this.entries.set(key, { value, expiresAt: this.now() + this.ttlMs });
    while (this.entries.size > this.maxSize) {
      const oldest = this.entries.keys().next().value as K;
      this.entries.delete(oldest);
    }
  }

  has(key: K): boolean {
    const entry = this.entries.get(key);
    if (!entry) return false;
    if (entry.expiresAt <= this.now()) {
      this.entries.delete(key);
      return false;
    }
    return true;
  }

  delete(key: K): boolean {
    return this.entries.delete(key);
  }

  clear(): void {
    this.entries.clear();
  }

  get size(): number {
    this.purgeExpired();
    return this.entries.size;
  }
}
```

How each spec clause is met:

- **Recency via Map order:** JavaScript Maps iterate in insertion order, so the head is always the least recently used entry. `get` refreshes recency by delete-and-reinsert (moving the key to the tail) *without* touching its expiry — reads extend position, not lifetime; only `set` renews the TTL.
- **has() is recency-neutral:** it checks and even cleans up an expired entry, but never re-inserts a live one — a monitoring probe can't accidentally keep a key alive in the eviction order.
- **Purge before evict:** `set` purges expired entries first, so a live entry is only evicted when the cache genuinely holds maxSize live entries; the eviction loop then removes from the head, which after the purge is the LRU live entry.
- **Injected clock:** all expiry logic reads `this.now()`, so tests advance a fake clock instead of sleeping — and production passes Date.now.

