function justify(words: string[], width: number): string[] {
  const lines: string[] = [];
  let i = 0;
  while (i < words.length) {
    let j = i;
    let lineLength = 0;
    while (j < words.length && lineLength + words[j].length + (j > i ? 1 : 0) <= width) {
      lineLength += words[j].length + (j > i ? 1 : 0);
      j++;
    }
    const lineWords = words.slice(i, j);
    const isLast = j === words.length;
    if (isLast || lineWords.length === 1) {
      const text = lineWords.join(" ");
      lines.push(text + " ".repeat(width - text.length));
    } else {
      const letters = lineWords.reduce((sum, w) => sum + w.length, 0);
      const gaps = lineWords.length - 1;
      const totalSpaces = width - letters;
      const base = Math.floor(totalSpaces / gaps);
      const extra = totalSpaces % gaps;
      let line = "";
      lineWords.forEach((word, index) => {
        if (index > 0) {
          line += " ".repeat(base + (index - 1 < extra ? 1 : 0));
        }
        line += word;
      });
      lines.push(line);
    }
    i = j;
  }
  return lines;
}

