interface BackoffOptions {
  baseMs: number;
  factor?: number;
  maxMs: number;
  attempts: number;
  jitter: "none" | "full" | "equal";
  rng: () => number;
}

function backoffDelays(options: BackoffOptions): number[] {
  const factor = options.factor ?? 2;
  const delays: number[] = [];
  for (let i = 0; i < options.attempts; i++) {
    const raw = Math.min(options.maxMs, options.baseMs * Math.pow(factor, i));
    let delay: number;
    switch (options.jitter) {
      case "none":
        delay = raw;
        break;
      case "full":
        delay = Math.floor(options.rng() * raw);
        break;
      case "equal":
        delay = Math.floor(raw / 2 + options.rng() * (raw / 2));
        break;
    }
    delays.push(delay);
  }
  return delays;
}
```

How each spec clause is met:

- **Cap before jitter:** the raw delay is clamped to maxMs *first*, and jitter is applied to the clamped value — so no jitter mode can ever produce a delay above maxMs. Applying jitter before the cap (or to the uncapped exponential) is a common ordering bug that lets "full" jitter exceed the intended ceiling on later attempts.
- **The three jitter modes:** "none" is the pure exponential ladder; "full" spreads delays over [0, raw), which maximally decorrelates competing clients; "equal" keeps half the delay fixed and jitters the other half — a floor of raw/2 guarantees forward progress while still spreading retries. These are the standard AWS-architecture-blog definitions.
- **Determinism by injection:** the rng is a parameter, so a test can pass () => 0.5 and assert the exact sequence — e.g. base 100, maxMs 1000, full jitter, rng 0.5 gives [50, 100, 200, 400, 500] with the last value visibly capped.
- **Integer delays:** "none" mode returns raw as-is per the formula (exact when baseMs and factor are integers); the jitter modes floor explicitly.

