function stableSortBy<T>(items: T[], key: (item: T) => number): T[] {
  if (items.length <= 1) return items.slice();
  const mid = Math.floor(items.length / 2);
  const left = stableSortBy(items.slice(0, mid), key);
  const right = stableSortBy(items.slice(mid), key);
  const merged: T[] = [];
  let i = 0;
  let j = 0;
  while (i < left.length && j < right.length) {
    if (key(left[i]) <= key(right[j])) {
      merged.push(left[i]);
      i++;
    } else {
      merged.push(right[j]);
      j++;
    }
  }
  return merged.concat(left.slice(i), right.slice(j));
}

const items = [
  { k: 2, id: "a" },
  { k: 1, id: "b" },
  { k: 2, id: "c" },
  { k: 1, id: "d" },
  { k: 3, id: "e" },
];
const sorted = stableSortBy(items, (x) => x.k);
console.log("sorted:", sorted.map((x) => x.id).join(""));
console.log("original:", items.map((x) => x.id).join(""));

