```typescript
interface RateLimitOptions {
  limit: number;
  windowMs: number;
  now: () => number;
}

interface RateLimitResult {
  allowed: boolean;
  remaining: number;
  retryAfterMs: number;
}

function createRateLimiter(options: RateLimitOptions) {
  const { limit, windowMs, now } = options;
  const buckets = new Map<string, number[]>();

  return function check(key: string): RateLimitResult {
    const t = now();
    const cutoff = t - windowMs;
    const stamps = (buckets.get(key) ?? []).filter((ts) => ts > cutoff);
    if (stamps.length < limit) {
      stamps.push(t);
      buckets.set(key, stamps);
      return { allowed: true, remaining: limit - stamps.length, retryAfterMs: 0 };
    }
    buckets.set(key, stamps);
    return {
      allowed: false,
      remaining: 0,
      retryAfterMs: stamps[0] + windowMs - t,
    };
  };
}
```

How each spec clause is met:

- **Window boundary:** the filter keeps `ts > cutoff`, i.e. drops timestamps exactly windowMs old — a request admitted at t=0 stops counting at t=windowMs exactly, which matches the retryAfter math: at the denial, retryAfterMs = oldest + windowMs − now is precisely when the oldest stamp ages out.
- **Denials are free:** the deny branch never pushes a timestamp — an attacker hammering the endpoint can't extend their own lockout, and the stored array is written back pruned, so buckets don't accumulate dead timestamps.
- **Remaining math:** after admission, remaining = limit − stamps.length where length already includes the just-admitted request — so the first request against a limit of 5 reports remaining 4, the count of *further* requests currently allowed.
- **Per-key isolation and clock injection:** keys live in separate arrays in one Map, and all time comes from the injected `now`, making the limiter unit-testable with a stepped fake clock. (Production note: the Map grows with distinct keys; pair it with a periodic sweep or an outer cache if keys are unbounded, e.g. raw IPs.)

```typescript
class JsonSubsetParser {
  private pos = 0;

  constructor(private text: string) {}

  parse(): unknown {
    const value = this.parseValue();
    this.skipWhitespace();
    if (this.pos !== this.text.length) {
      throw this.error("trailing content after top-level value");
    }
    return value;
  }

  private error(message: string): SyntaxError {
    return new SyntaxError(`${message} at position ${this.pos}`);
  }

  private peek(): string {
    return this.pos < this.text.length ? this.text[this.pos] : "";
  }

  private skipWhitespace(): void {
    while (this.pos < this.text.length && " \t\n\r".includes(this.text[this.pos])) {
      this.pos++;
    }
  }

  private parseValue(): unknown {
    this.skipWhitespace();
    const ch = this.peek();
    switch (ch) {
      case "{":
        return this.parseObject();
      case "[":
        return this.parseArray();
      case '"':
        return this.parseString();
      case "t":
        return this.parseLiteral("true", true);
      case "f":
        return this.parseLiteral("false", false);
      case "n":
        return this.parseLiteral("null", null);
      default:
        if (ch === "-" || (ch >= "0" && ch <= "9")) {
          return this.parseNumber();
        }
        throw this.error(`unexpected character '${ch}'`);
    }
  }

  private parseLiteral(word: string, value: unknown): unknown {
    if (!this.text.startsWith(word, this.pos)) {
      throw this.error(`invalid literal, expected ${word}`);
    }
    this.pos += word.length;
    return value;
  }

  private parseObject(): Record<string, unknown> {
    const result: Record<string, unknown> = {};
    this.pos++; // consume {
    this.skipWhitespace();
    if (this.peek() === "}") {
      this.pos++;
      return result;
    }
    while (true) {
      this.skipWhitespace();
      if (this.peek() !== '"') throw this.error("expected string key");
      const key = this.parseString();
      this.skipWhitespace();
      if (this.peek() !== ":") throw this.error("expected ':' after object key");
      this.pos++;
      result[key] = this.parseValue();
      this.skipWhitespace();
      const ch = this.peek();
      if (ch === ",") {
        this.pos++;
      } else if (ch === "}") {
        this.pos++;
        return result;
      } else {
        throw this.error("expected ',' or '}' in object");
      }
    }
  }

  private parseArray(): unknown[] {
    const result: unknown[] = [];
    this.pos++; // consume [
    this.skipWhitespace();
    if (this.peek() === "]") {
      this.pos++;
      return result;
    }
    while (true) {
      result.push(this.parseValue());
      this.skipWhitespace();
      const ch = this.peek();
      if (ch === ",") {
        this.pos++;
      } else if (ch === "]") {
        this.pos++;
        return result;
      } else {
        throw this.error("expected ',' or ']' in array");
      }
    }
  }

  private parseString(): string {
    let out = "";
    this.pos++; // consume opening quote
    while (true) {
      if (this.pos >= this.text.length) throw this.error("unterminated string");
      const ch = this.text[this.pos++];
      if (ch === '"') return out;
      if (ch === "\\") {
        if (this.pos >= this.text.length) throw this.error("unterminated escape");
        const esc = this.text[this.pos++];
        switch (esc) {
          case '"': out += '"'; break;
          case "\\": out += "\\"; break;
          case "/": out += "/"; break;
          case "b": out += "\b"; break;
          case "f": out += "\f"; break;
          case "n": out += "\n"; break;
          case "r": out += "\r"; break;
          case "t": out += "\t"; break;
          case "u": {
            const hex = this.text.slice(this.pos, this.pos + 4);
            if (!/^[0-9a-fA-F]{4}$/.test(hex)) throw this.error("invalid unicode escape");
            out += String.fromCharCode(parseInt(hex, 16));
            this.pos += 4;
            break;
          }
          default:
            throw this.error(`invalid escape '\\${esc}'`);
        }
      } else {
        out += ch;
      }
    }
  }

  private parseNumber(): number {
    const start = this.pos;
    if (this.peek() === "-") this.pos++;
    if (this.peek() === "0") {
      this.pos++;
    } else if (this.peek() >= "1" && this.peek() <= "9") {
      while (this.peek() >= "0" && this.peek() <= "9") this.pos++;
    } else {
      throw this.error("invalid number");
    }
    if (this.peek() === "0" || (this.peek() >= "1" && this.peek() <= "9")) {
      throw this.error("leading zeros are not allowed");
    }
    if (this.peek() === ".") {
      this.pos++;
      if (!(this.peek() >= "0" && this.peek() <= "9")) throw this.error("digit required after decimal point");
      while (this.peek() >= "0" && this.peek() <= "9") this.pos++;
    }
    if (this.peek() === "e" || this.peek() === "E") {
      this.pos++;
      if (this.peek() === "+" || this.peek() === "-") this.pos++;
      if (!(this.peek() >= "0" && this.peek() <= "9")) throw this.error("digit required in exponent");
      while (this.peek() >= "0" && this.peek() <= "9") this.pos++;
    }
    return Number(this.text.slice(start, this.pos));
  }
}

function parseJsonSubset(text: string): unknown {
  return new JsonSubsetParser(text).parse();
}
```

How each spec clause is met:

- **Positions in every error:** all failures go through `error()`, which appends the cursor position — including trailing content, which is checked in `parse()` after the top-level value and its surrounding whitespace.
- **Leading zeros:** the number parser consumes a lone 0 *or* a 1–9-led digit run, then explicitly checks whether another digit follows the lone-zero branch — `01` fails with the named error rather than parsing as 0 with trailing junk (which would surface as a confusing error elsewhere).
- **String strictness:** running off the end inside a string is \"unterminated string\"; an unknown escape letter hits the `default` case; `\\u` demands exactly four hex digits before consuming them.
- **Structure errors:** objects demand a string key, then a colon, then a value, then comma-or-brace — a missing comma or colon therefore throws at the exact position of the offending character, and arrays mirror the same discipline. Duplicate object keys take the last value, matching JSON.parse.

