interface SaleRow {
  region: string;
  product: string;
  units: number;
  unitPriceCents: number;
}

interface RegionSummary {
  region: string;
  orders: number;
  units: number;
  revenueCents: number;
  topProduct: string;
}

function summarizeSales(rows: SaleRow[]): RegionSummary[] {
  const byRegion = new Map<string, {
    orders: number;
    units: number;
    revenueCents: number;
    productRevenue: Map<string, number>;
  }>();

  for (const row of rows) {
    let agg = byRegion.get(row.region);
    if (!agg) {
      agg = { orders: 0, units: 0, revenueCents: 0, productRevenue: new Map() };
      byRegion.set(row.region, agg);
    }
    const lineRevenue = row.units * row.unitPriceCents;
    agg.orders += 1;
    agg.units += row.units;
    agg.revenueCents += lineRevenue;
    agg.productRevenue.set(
      row.product,
      (agg.productRevenue.get(row.product) ?? 0) + lineRevenue,
    );
  }

  const summaries: RegionSummary[] = [];
  for (const [region, agg] of byRegion) {
    let topProduct = "";
    let topRevenue = -1;
    for (const [product, revenue] of agg.productRevenue) {
      if (revenue > topRevenue || (revenue === topRevenue && product < topProduct)) {
        topProduct = product;
        topRevenue = revenue;
      }
    }
    summaries.push({
      region,
      orders: agg.orders,
      units: agg.units,
      revenueCents: agg.revenueCents,
      topProduct,
    });
  }

  summaries.sort((a, b) =>
    b.revenueCents - a.revenueCents || (a.region < b.region ? -1 : a.region > b.region ? 1 : 0),
  );
  return summaries;
}

const rows: SaleRow[] = [
  { region: "north", product: "widget", units: 3, unitPriceCents: 1000 },
  { region: "north", product: "gadget", units: 2, unitPriceCents: 2500 },
  { region: "south", product: "widget", units: 5, unitPriceCents: 1000 },
  { region: "north", product: "widget", units: 1, unitPriceCents: 1000 },
  { region: "south", product: "gadget", units: 1, unitPriceCents: 2500 },
];
console.log(JSON.stringify(summarizeSales(rows)));
